package apiserver

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

// The bundled OpenAPI document generated by packages/contracts (`pnpm gen`). Responses are
// validated against its component schemas so the Go handlers cannot drift from the contract
// the TypeScript client is generated from.
const openAPIPath = "../../../packages/contracts/src/generated/openapi.json"

func contractSchema(t *testing.T, component string) *jsonschema.Schema {
	t.Helper()
	raw, err := os.ReadFile(filepath.FromSlash(openAPIPath))
	if err != nil {
		t.Fatalf("read OpenAPI bundle (run `pnpm gen`): %v", err)
	}
	var doc struct {
		Components struct {
			Schemas json.RawMessage `json:"schemas"`
		} `json:"components"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatal(err)
	}
	// Re-root the component schemas as JSON Schema 2020-12 $defs.
	defs := strings.ReplaceAll(string(doc.Components.Schemas), "#/components/schemas/", "#/$defs/")
	root, err := jsonschema.UnmarshalJSON(strings.NewReader(`{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":` + defs + `}`))
	if err != nil {
		t.Fatal(err)
	}
	c := jsonschema.NewCompiler()
	c.AssertFormat()
	c.RegisterFormat(&jsonschema.Format{Name: "int64", Validate: func(any) error { return nil }})
	if err := c.AddResource("urn:matecollab:openapi:components", root); err != nil {
		t.Fatal(err)
	}
	s, err := c.Compile("urn:matecollab:openapi:components#/$defs/" + component)
	if err != nil {
		t.Fatalf("compile %s: %v", component, err)
	}
	return s
}

func validateBody(t *testing.T, s *jsonschema.Schema, body []byte) {
	t.Helper()
	v, err := jsonschema.UnmarshalJSON(bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	if err := s.Validate(v); err != nil {
		t.Fatalf("response does not match the contract: %v\nbody: %s", err, body)
	}
}

func TestConfigMatchesContract(t *testing.T) {
	w := httptest.NewRecorder()
	testRouter(t).ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/api/v1/config", nil))
	if w.Code != http.StatusOK || w.Header().Get("Cache-Control") != "no-cache" {
		t.Fatalf("status %d, cache-control %q", w.Code, w.Header().Get("Cache-Control"))
	}
	validateBody(t, contractSchema(t, "RuntimeConfig"), w.Body.Bytes())
}

func TestProblemsMatchContract(t *testing.T) {
	schema := contractSchema(t, "ProblemDetails")
	for _, tc := range []struct{ method, path string }{
		{http.MethodGet, "/api/v1/does-not-exist"},
		{http.MethodPost, "/api/v1/config"},
	} {
		w := httptest.NewRecorder()
		testRouter(t).ServeHTTP(w, httptest.NewRequest(tc.method, tc.path, nil))
		if ct := w.Header().Get("Content-Type"); ct != "application/problem+json" {
			t.Fatalf("%s %s: content type %q", tc.method, tc.path, ct)
		}
		validateBody(t, schema, w.Body.Bytes())
	}
}
